/** Accredited Nigerian tertiary institutions, grouped by type.
 *  Merged from the NARR institution register (universities, polytechnics,
 *  colleges of education) plus the Hipolabs university list, de-duplicated by
 *  normalised name. Baked in so the education form needs no runtime API key.
 *  469 institutions — College of Education: 91 · Polytechnic: 129 · University: 249. */
export type InstitutionType = "University" | "Polytechnic" | "College of Education";

export type Institution = { name: string; type: InstitutionType; acronym?: string; ownership?: string };

/** Types offered in the picker. "Other / International" lets anyone who studied
 *  outside Nigeria type their own school instead of picking from the list. */
export const INSTITUTION_TYPES = ["University", "Polytechnic", "College of Education", "Other / International"] as const;
export type InstitutionTypeChoice = (typeof INSTITUTION_TYPES)[number];

